<?php
namespace App\Http\Controllers;
use App\Models\{Appointment,AppointmentConfirmation,Company};
use App\Services\AppointmentReminder;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class PublicConfirmationController extends Controller {
 private function resolve(string $token):AppointmentConfirmation{abort_unless(preg_match('/^[a-f0-9]{64}$/',$token),404);return AppointmentConfirmation::where('token_hash',hash('sha256',$token))->firstOrFail();}
 private function available(AppointmentConfirmation $link,Appointment $a):bool {return app(AppointmentReminder::class)->valid($link,$a)&&(in_array($a->status,['scheduled','confirmed'],true)||($a->status==='cancelled'&&$link->response==='cancelled'));}
 private function page(?Appointment $appointment,?AppointmentConfirmation $link,int $status=200){return response()->view('reminders.public',compact('appointment','link'),$status)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer')->header('X-Robots-Tag','noindex, nofollow, nosnippet')->header('Content-Security-Policy',"default-src 'self'; style-src 'self'; img-src 'self' data:; form-action 'self'; frame-ancestors 'none'; base-uri 'self'");}
 public function show(string $token){$link=$this->resolve($token);$a=Appointment::forCompany((int)$link->company_id)->with(['company','professional'=>fn($q)=>$q->where('company_id',$link->company_id)])->findOrFail($link->appointment_id);if(!$this->available($link,$a))return $this->page(null,null,410);return $this->page($a,$link);}
 public function respond(Request $r,string $token){$r->validate(['choice'=>'required|in:confirmed,cancelled','acknowledge'=>'accepted']);$initial=$this->resolve($token);$valid=DB::transaction(function()use($r,$initial){Company::whereKey($initial->company_id)->lockForUpdate()->firstOrFail();$link=AppointmentConfirmation::forCompany((int)$initial->company_id)->whereKey($initial->id)->lockForUpdate()->firstOrFail();$a=Appointment::forCompany((int)$link->company_id)->with(['company','professional'=>fn($q)=>$q->where('company_id',$link->company_id)])->lockForUpdate()->findOrFail($link->appointment_id);if(!$this->available($link,$a))return false;$choice=$r->input('choice');if($link->response===$choice)return true;if($a->status==='cancelled')return false;$a->update(['status'=>$choice]);app(\App\Services\FollowupScheduling::class)->release($a,null,'Cancelamento pelo link do paciente.');$link->update(['response'=>$choice,'responded_at'=>now()]);return true;},3);if(!$valid)return $this->page(null,null,410);return redirect()->route('confirmation.show',$token)->with('success',$r->input('choice')==='confirmed'?'Presença confirmada.':'Agendamento cancelado. Para remarcar, fale com a clínica.')->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
}
